CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, name text NOT NULL, role text NOT NULL CHECK(role IN ('student','mentor','staff')), headline text NOT NULL, tags jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY, "ownerId" text NOT NULL REFERENCES users(id), title text NOT NULL, summary text NOT NULL, "courseOrClub" text NOT NULL, term text NOT NULL, tags jsonb NOT NULL DEFAULT '[]', status text NOT NULL CHECK(status IN ('ongoing','finished','paused')), "codeUrl" text, "demoUrl" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lessons (id text PRIMARY KEY, "projectId" text NOT NULL REFERENCES projects(id), "authorId" text NOT NULL REFERENCES users(id), type text NOT NULL CHECK(type IN ('worked','pitfall','next_team')), title text NOT NULL, assumed text NOT NULL, happened text NOT NULL, change text NOT NULL, conditions text NOT NULL, artifacts jsonb NOT NULL DEFAULT '[]', "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS comments (id text PRIMARY KEY, "lessonId" text NOT NULL REFERENCES lessons(id), "authorId" text NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN ('question','comment','reply')), body text NOT NULL, "parentId" text REFERENCES comments(id), "referralId" text, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS referrals (id text PRIMARY KEY, "lessonId" text NOT NULL REFERENCES lessons(id), "questionCommentId" text NOT NULL REFERENCES comments(id), "mentorId" text NOT NULL REFERENCES users(id), "staffId" text NOT NULL REFERENCES users(id), reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')), "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("questionCommentId","mentorId"));
CREATE TABLE IF NOT EXISTS adoptions (id text PRIMARY KEY, "lessonId" text NOT NULL REFERENCES lessons(id), "adoptingProjectId" text NOT NULL REFERENCES projects(id), "authorId" text NOT NULL REFERENCES users(id), result text CHECK(result IN ('worked','partial','failed')), note text NOT NULL DEFAULT '', "artifactUrl" text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("lessonId","adoptingProjectId"), CHECK(result IS NULL OR length(trim(note)) > 0));
CREATE INDEX IF NOT EXISTS lessons_project_idx ON lessons("projectId");
CREATE INDEX IF NOT EXISTS comments_lesson_idx ON comments("lessonId");
CREATE INDEX IF NOT EXISTS adoptions_project_idx ON adoptions("adoptingProjectId");
